A, F, M = "artifacts", "fossils", "minerals"
R = []  # (slug, name, kind, specialty, state, covers, region, contact, contact_url, availability, source_url)
def add(slug, name, kind, spec, state, contact, url, avail, src=None, covers=None, region=None):
    R.append(dict(slug=slug, name=name, kind=kind, specialty=spec, state=state, covers=covers or [state], region=region or state, contact=contact, contact_url=url, availability=avail, source_url=src or url))
