for i, r in enumerate(R): r["sort"] = 1000 + i * 10; r["last_verified"] = V
if __name__ == "__main__":
    q = lambda v: "null" if v is None else "'" + str(v).replace("'", "''") + "'"
    arr = lambda a: "array[" + ",".join(q(x) for x in a) + "]::text[]"
    rows = [f"({q(r['slug'])},{q(r['name'])},{q(r['kind'])},{arr(r['specialty'])},{q(r['region'])},{q(r['state'])},{arr(r['covers'])},{q(r['contact'])},{q(r['contact_url'])},{q(r['availability'])},{q(r['source_url'])},'{V}',{r['sort']})" for r in R]
    print("insert into public.texas_resources (slug,name,kind,specialty,region,state,covers,contact,contact_url,availability,source_url,last_verified,sort) values\n" + ",\n".join(rows) +
          "\non conflict (slug) do update set name=excluded.name,kind=excluded.kind,specialty=excluded.specialty,region=excluded.region,state=excluded.state,covers=excluded.covers,contact=excluded.contact,contact_url=excluded.contact_url,availability=excluded.availability,source_url=excluded.source_url,last_verified=excluded.last_verified,sort=excluded.sort,updated_at=now();")
    if "--json" in sys.argv:
        p = pathlib.Path(__file__).resolve().parents[2] / "data/texas-resources.json"; old = [x for x in json.load(open(p)) if x.get("state", "Texas") == "Texas"]
        for x in old: x["state"] = "Texas"; x["covers"] = ["Texas"]
        json.dump(old + [{k: v for k, v in r.items()} for r in R], open(p, "w"), indent=1, ensure_ascii=False)
        print(f"-- json: {len(old)} Texas + {len(R)} new", file=sys.stderr)
